CREATE TABLE institutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,kind text NOT NULL CHECK(kind IN('B2B','B2C')));
CREATE TABLE batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institution_id uuid NOT NULL REFERENCES institutions(id),name text NOT NULL,capacity integer NOT NULL DEFAULT 40 CHECK(capacity>0));
CREATE TABLE groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),name text NOT NULL,UNIQUE(batch_id,name));
CREATE TABLE role_assignments(user_id text PRIMARY KEY REFERENCES "user"(id),role text NOT NULL CHECK(role IN('student','trainer','college_coordinator','organiser','super_admin')),institution_id uuid REFERENCES institutions(id),CHECK(role<>'college_coordinator' OR institution_id IS NOT NULL));
CREATE TABLE student_profiles(user_id text PRIMARY KEY REFERENCES "user"(id),group_id uuid NOT NULL REFERENCES groups(id),dos_id text UNIQUE,course text,department text,academic_year text,github_url text,linkedin_url text);
CREATE TABLE workshops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,objective text NOT NULL);
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workshop_id uuid NOT NULL REFERENCES workshops(id),group_id uuid NOT NULL REFERENCES groups(id),trainer_id text REFERENCES "user"(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,mode text NOT NULL CHECK(mode IN('Online','Offline','Hybrid')),venue text NOT NULL,evidence_required boolean NOT NULL,evidence_types text[] NOT NULL DEFAULT '{}',evidence_deadline timestamptz,closed_at timestamptz,CHECK(ends_at>starts_at),CHECK((NOT evidence_required AND evidence_deadline IS NULL AND cardinality(evidence_types)=0) OR (evidence_required AND evidence_deadline>ends_at AND cardinality(evidence_types)>0)));
CREATE TABLE attendance(student_id text NOT NULL REFERENCES student_profiles(user_id),session_id uuid NOT NULL REFERENCES sessions(id),status text NOT NULL CHECK(status IN('Not Started','Checked In','Completed','Late','Partial','Absent – Unconfirmed','Absent – Confirmed','Excused','Manually Confirmed')),source text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(student_id,session_id));
CREATE TABLE submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id text NOT NULL REFERENCES student_profiles(user_id),session_id uuid NOT NULL REFERENCES sessions(id),type text NOT NULL,reference text NOT NULL,submitted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(student_id,session_id));
CREATE TABLE certifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id text NOT NULL REFERENCES student_profiles(user_id),title text NOT NULL,provider text NOT NULL,completed_on date NOT NULL,reference text NOT NULL,status text NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Verified')));
CREATE TABLE tool_confidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id text NOT NULL REFERENCES student_profiles(user_id),tool text NOT NULL,reflection text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id text NOT NULL,actor_role text NOT NULL,entity text NOT NULL,entity_id text NOT NULL,before_value jsonb,after_value jsonb,reason text NOT NULL CHECK(length(trim(reason))>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION protect_audit_events() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit events are append-only'; END $$;
CREATE TRIGGER immutable_audit_rows BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION protect_audit_events();
CREATE TRIGGER immutable_audit_table BEFORE TRUNCATE ON audit_events FOR EACH STATEMENT EXECUTE FUNCTION protect_audit_events();
CREATE INDEX sessions_group ON sessions(group_id,starts_at);CREATE INDEX audit_entity ON audit_events(entity,entity_id,created_at);CREATE INDEX profiles_group ON student_profiles(group_id);
